const extracted = $input.first().json.output;
const documents = $("When Executed by Another Workflow").first().json.documents;

const errors = [];
const warnings = [];
const validStatuses = new Set([
  "confirmed",
  "disputed",
  "proposed"
]);

const sourceMap = new Map(
  documents.map(doc => [doc.source_id, doc])
);

const normalize = text =>
  String(text || "").replace(/\s+/g, " ").trim();

const requirements = [
  ...(extracted.functional_requirements || []),
  ...(extracted.non_functional_requirements || [])
];

const seenIds = new Set();
let evidenceChecked = 0;

for (const req of requirements) {

const idMatch = /^(FR|NFR)-(\d{1,3})$/.exec(req.id || "");

if (!idMatch) {
  errors.push(`Invalid requirement ID: ${req.id}`);
} else {
  req.id = `${idMatch[1]}-${idMatch[2].padStart(2, "0")}`;
}


  if (seenIds.has(req.id)) {
    errors.push(`Duplicate requirement ID: ${req.id}`);
  }
  seenIds.add(req.id);

  if (!validStatuses.has(req.status)) {
    errors.push(`${req.id}: Invalid status '${req.status}'`);
  }

  if (!Array.isArray(req.sources) || req.sources.length === 0) {
    errors.push(`${req.id}: No source evidence provided`);
    continue;
  }

  for (const source of req.sources) {
    const original = sourceMap.get(source.source_id);

    if (!original) {
      errors.push(`${req.id}: Unknown source ${source.source_id}`);
      continue;
    }

    if (source.file_name !== original.file_name) {
      errors.push(`${req.id}: Filename does not match source ID`);
    }

    const evidence = normalize(source.evidence);
    const originalText = normalize(original.content);

if (!evidence || !originalText.includes(evidence)) {
  errors.push(
    `${req.id}: Evidence not found in ${source.source_id}. ` +
    `AI quotation: "${source.evidence}"`
  );
} else {
      evidenceChecked++;
    }
  }
}

if (requirements.length === 0) {
  warnings.push("No requirements extracted.");
}

if (extracted.insufficient_information === true) {
  warnings.push("Extractor marked input as insufficient.");
}

const validationPassed = errors.length === 0;

return [{
  json: {
    test_id: $("When Executed by Another Workflow").first().json.test_id,
    output: extracted,
    validation: {
      passed: validationPassed,
      total_requirements: requirements.length,
      evidence_verified: evidenceChecked,
      error_count: errors.length,
      warning_count: warnings.length,
      errors,
      warnings
    }
  }
}];

const prd = $input.first().json.text || "";

const extracted = $("Requirement Extractor")
  .first().json.output;

const errors = [];
const warnings = [];

const requiredSections = [
  "Product Overview",
  "Goals and Objectives",
  "User Personas",
  "Feature Requirements",
  "Acceptance Criteria",
  "Out of Scope",
  "Dependencies",
  "Assumptions",
  "Open Questions",
  "Timeline"
];

// Check the 10 required PRD sections.
for (const section of requiredSections) {
  const found = prd
    .toLowerCase()
    .includes(section.toLowerCase());

  if (!found) {
    errors.push(`Missing PRD section: ${section}`);
  }
}

// Collect requirement IDs from extracted JSON.
const requirements = [
  ...(extracted.functional_requirements || []),
  ...(extracted.non_functional_requirements || [])
];

const normalizeId = id => {
  const match = /^(FR|NFR)-(\d+)$/.exec(id || "");
  if (!match) return id;
  return `${match[1]}-${match[2].padStart(2, "0")}`;
};

const missingRequirements = [];

for (const req of requirements) {
  const id = normalizeId(req.id);

  const pattern = new RegExp(
    `\\b${id.replace("-", "\\-")}\\b`
  );

  if (!pattern.test(prd)) {
    missingRequirements.push(id);
  }
}

if (missingRequirements.length > 0) {
  errors.push(
    `Missing requirement IDs: ${missingRequirements.join(", ")}`
  );
}

const passed = errors.length === 0;

return [{
  json: {
    text: prd,
    prd_validation: {
      passed,
      required_sections: requiredSections.length,
      total_requirements: requirements.length,
      missing_requirements: missingRequirements,
      error_count: errors.length,
      warning_count: warnings.length,
      errors,
      warnings
    }
  }
}];
